			bool is_variadic_placeholder = arg->kind == ZEND_AST_PLACEHOLDER_ARG
				&& arg->attr == ZEND_PLACEHOLDER_VARIADIC;

			if (uses_named_args && !is_variadic_placeholder) {
				zend_error_noreturn(E_COMPILE_ERROR,
